-- REQ-003/004/005/009/010/011/012/013: review-only entity draft.
-- NOT in migrations/. NOT wired to application routes. No production grants or formulas.
-- Apply only to a disposable synthetic DB for syntax/FK/RLS checks.
begin;
create schema cbc_demo_draft;
revoke all on schema cbc_demo_draft from public, anon, authenticated;
create table cbc_demo_draft.programs (id uuid primary key default gen_random_uuid(), name text not null, notes text);
alter table cbc_demo_draft.programs enable row level security;
revoke all on cbc_demo_draft.programs from public,anon,authenticated;
create table cbc_demo_draft.events (id uuid primary key default gen_random_uuid(), name text not null, program_id uuid references cbc_demo_draft.programs(id), occurs_at timestamptz);
alter table cbc_demo_draft.events enable row level security;
revoke all on cbc_demo_draft.events from public,anon,authenticated;
create table cbc_demo_draft.cohorts (id uuid primary key default gen_random_uuid(), program_id uuid references cbc_demo_draft.programs(id), label text);
alter table cbc_demo_draft.cohorts enable row level security;
revoke all on cbc_demo_draft.cohorts from public,anon,authenticated;
create table cbc_demo_draft.opportunities (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id), contact_id uuid references public.contacts(id), program_id uuid references cbc_demo_draft.programs(id), stage text, estimated_amount numeric, notes text);
alter table cbc_demo_draft.opportunities enable row level security;
revoke all on cbc_demo_draft.opportunities from public,anon,authenticated;
create table cbc_demo_draft.agreements (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id), contact_id uuid references public.contacts(id), start_date date, end_date date);
alter table cbc_demo_draft.agreements enable row level security;
revoke all on cbc_demo_draft.agreements from public,anon,authenticated;
create table cbc_demo_draft.contributions (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id), contact_id uuid references public.contacts(id), agreement_id uuid references cbc_demo_draft.agreements(id), program_id uuid references cbc_demo_draft.programs(id), event_id uuid references cbc_demo_draft.events(id), contribution_date date, amount numeric, contribution_type text, sponsorship_level text, funding_status text);
alter table cbc_demo_draft.contributions enable row level security;
revoke all on cbc_demo_draft.contributions from public,anon,authenticated;
create table cbc_demo_draft.commitments (id uuid primary key default gen_random_uuid(), contribution_id uuid references cbc_demo_draft.contributions(id), amount numeric, committed_on date);
alter table cbc_demo_draft.commitments enable row level security;
revoke all on cbc_demo_draft.commitments from public,anon,authenticated;
create table cbc_demo_draft.receipts (id uuid primary key default gen_random_uuid(), contribution_id uuid references cbc_demo_draft.contributions(id), commitment_id uuid references cbc_demo_draft.commitments(id), amount numeric, received_on date);
alter table cbc_demo_draft.receipts enable row level security;
revoke all on cbc_demo_draft.receipts from public,anon,authenticated;
create table cbc_demo_draft.activities (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id), occurred_at timestamptz, activity_type text, location text, purpose text, key_discussion text, sponsor_needs text, cbc_opportunity text, outcome text);
alter table cbc_demo_draft.activities enable row level security;
revoke all on cbc_demo_draft.activities from public,anon,authenticated;
create table cbc_demo_draft.activity_contacts (id uuid primary key default gen_random_uuid(), activity_id uuid references cbc_demo_draft.activities(id), contact_id uuid references public.contacts(id), unique(activity_id, contact_id));
alter table cbc_demo_draft.activity_contacts enable row level security;
revoke all on cbc_demo_draft.activity_contacts from public,anon,authenticated;
create table cbc_demo_draft.tasks (id uuid primary key default gen_random_uuid(), activity_id uuid references cbc_demo_draft.activities(id), organization_id uuid references public.organizations(id), contact_id uuid references public.contacts(id), owner_id uuid references public.profiles(id), description text, due_date date, completed_at timestamptz);
alter table cbc_demo_draft.tasks enable row level security;
revoke all on cbc_demo_draft.tasks from public,anon,authenticated;
create table cbc_demo_draft.sponsor_interests (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id), category text, strength text, notes text, opportunity_id uuid references cbc_demo_draft.opportunities(id));
alter table cbc_demo_draft.sponsor_interests enable row level security;
revoke all on cbc_demo_draft.sponsor_interests from public,anon,authenticated;
create table cbc_demo_draft.interest_programs (id uuid primary key default gen_random_uuid(), interest_id uuid references cbc_demo_draft.sponsor_interests(id), program_id uuid references cbc_demo_draft.programs(id), unique(interest_id,program_id));
alter table cbc_demo_draft.interest_programs enable row level security;
revoke all on cbc_demo_draft.interest_programs from public,anon,authenticated;
create table cbc_demo_draft.interest_activities (id uuid primary key default gen_random_uuid(), interest_id uuid references cbc_demo_draft.sponsor_interests(id), activity_id uuid references cbc_demo_draft.activities(id), unique(interest_id,activity_id));
alter table cbc_demo_draft.interest_activities enable row level security;
revoke all on cbc_demo_draft.interest_activities from public,anon,authenticated;
create table cbc_demo_draft.enrollments (id uuid primary key default gen_random_uuid(), participant_id uuid references public.contacts(id), cohort_id uuid references cbc_demo_draft.cohorts(id), support_amount numeric, education_level text, institution text, field_of_study text, graduation_status text, graduation_date date, employment_status text, employment_field text);
alter table cbc_demo_draft.enrollments enable row level security;
revoke all on cbc_demo_draft.enrollments from public,anon,authenticated;
create table cbc_demo_draft.mentorship_pairs (id uuid primary key default gen_random_uuid(), mentor_id uuid references public.contacts(id), mentee_id uuid references public.contacts(id), cohort_id uuid references cbc_demo_draft.cohorts(id), start_date date, target_end_date date, status text, checkin_frequency text, issues text, task_id uuid references cbc_demo_draft.tasks(id));
alter table cbc_demo_draft.mentorship_pairs enable row level security;
revoke all on cbc_demo_draft.mentorship_pairs from public,anon,authenticated;
create table cbc_demo_draft.checkins (id uuid primary key default gen_random_uuid(), pair_id uuid references cbc_demo_draft.mentorship_pairs(id), occurred_at timestamptz, completed_at timestamptz, notes text);
alter table cbc_demo_draft.checkins enable row level security;
revoke all on cbc_demo_draft.checkins from public,anon,authenticated;
create table cbc_demo_draft.feedback (id uuid primary key default gen_random_uuid(), pair_id uuid references cbc_demo_draft.mentorship_pairs(id), respondent_id uuid references public.contacts(id), recorded_at timestamptz, score numeric);
alter table cbc_demo_draft.feedback enable row level security;
revoke all on cbc_demo_draft.feedback from public,anon,authenticated;
create table cbc_demo_draft.memberships (id uuid primary key default gen_random_uuid(), contact_id uuid references public.contacts(id), member_organization_id uuid references public.organizations(id), organization_id uuid references public.organizations(id), membership_type text, industry text, start_date date, renewal_date date, fee numeric, payment_status text, check ((contact_id is null) <> (member_organization_id is null)));
alter table cbc_demo_draft.memberships enable row level security;
revoke all on cbc_demo_draft.memberships from public,anon,authenticated;
create table cbc_demo_draft.attendance (id uuid primary key default gen_random_uuid(), contact_id uuid references public.contacts(id), event_id uuid references cbc_demo_draft.events(id), attended_at timestamptz);
alter table cbc_demo_draft.attendance enable row level security;
revoke all on cbc_demo_draft.attendance from public,anon,authenticated;
create table cbc_demo_draft.volunteer_logs (id uuid primary key default gen_random_uuid(), contact_id uuid references public.contacts(id), activity_id uuid references cbc_demo_draft.activities(id), hours numeric);
alter table cbc_demo_draft.volunteer_logs enable row level security;
revoke all on cbc_demo_draft.volunteer_logs from public,anon,authenticated;
create table cbc_demo_draft.documents (id uuid primary key default gen_random_uuid(), name text not null, document_type text, version text, effective_date date, expiry_date date, access_level text, status text, owner_id uuid references public.profiles(id), uploaded_by uuid references public.profiles(id), uploaded_at timestamptz default now(), updated_at timestamptz default now(), external_reference text);
alter table cbc_demo_draft.documents enable row level security;
revoke all on cbc_demo_draft.documents from public,anon,authenticated;
create table cbc_demo_draft.document_versions (id uuid primary key default gen_random_uuid(), document_id uuid references cbc_demo_draft.documents(id), version text, external_reference text);
alter table cbc_demo_draft.document_versions enable row level security;
revoke all on cbc_demo_draft.document_versions from public,anon,authenticated;
create table cbc_demo_draft.document_organizations (id uuid primary key default gen_random_uuid(), document_id uuid references cbc_demo_draft.documents(id), organization_id uuid references public.organizations(id));
alter table cbc_demo_draft.document_organizations enable row level security;
revoke all on cbc_demo_draft.document_organizations from public,anon,authenticated;
create table cbc_demo_draft.document_contacts (id uuid primary key default gen_random_uuid(), document_id uuid references cbc_demo_draft.documents(id), contact_id uuid references public.contacts(id));
alter table cbc_demo_draft.document_contacts enable row level security;
revoke all on cbc_demo_draft.document_contacts from public,anon,authenticated;
create table cbc_demo_draft.document_programs (id uuid primary key default gen_random_uuid(), document_id uuid references cbc_demo_draft.documents(id), program_id uuid references cbc_demo_draft.programs(id));
alter table cbc_demo_draft.document_programs enable row level security;
revoke all on cbc_demo_draft.document_programs from public,anon,authenticated;
create table cbc_demo_draft.document_events (id uuid primary key default gen_random_uuid(), document_id uuid references cbc_demo_draft.documents(id), event_id uuid references cbc_demo_draft.events(id));
alter table cbc_demo_draft.document_events enable row level security;
revoke all on cbc_demo_draft.document_events from public,anon,authenticated;
create table cbc_demo_draft.document_agreements (id uuid primary key default gen_random_uuid(), document_id uuid references cbc_demo_draft.documents(id), agreement_id uuid references cbc_demo_draft.agreements(id));
alter table cbc_demo_draft.document_agreements enable row level security;
revoke all on cbc_demo_draft.document_agreements from public,anon,authenticated;
create table cbc_demo_draft.funding_targets (id uuid primary key default gen_random_uuid(), period_start date, period_end date, amount numeric, notes text);
alter table cbc_demo_draft.funding_targets enable row level security;
revoke all on cbc_demo_draft.funding_targets from public,anon,authenticated;
commit;
